  body {
    margin: 0;
  }

  #react {
    height: 100%;
    width: 100%;
  }

  .card {
    min-width: 0;
    min-height: 120px;
    display: flex;
    flex-direction: column;
    justify-content: center;
    padding: 12px 24px;
    border-radius: 4px;
    border: 1px solid #cccccc;
    box-shadow: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
    background-color: var(--background-surface);
  }



  .content {
    font-size: 12px;
    line-height: 18px;
    font-weight: 400;
    flex-wrap: wrap; /* Add this to allow wrapping of images to new rows */
    gap: 20px; /* Add this to create space between images */
    align-items: center;
    display: column;
  }

  .filters {
  display: flex;
  gap: 20px;
  margin-bottom: 20px;
  padding: 5px;
  position: fixed;
  top: 20;
  left: 20;
  width: 60%;
  z-index: 1000; /* Ensure it appears above other content */
  background-color: white
}

  .hide-tos{
  background-color: white;
  border: 1px solid black;
  padding: 3px;
}

  .image-grid {
    display: flex;
    flex-wrap: wrap;
    gap: 5px;
    margin-top: 50px
  }



    .image-container {
  position: relative;
  display: inline-block;
  }

  .image-checkbox {
    position: absolute;
    top: 20px;
    right: 20px;
    transform: scale(3)
  }

  .image-checkbox:checked {
  appearance: none;
  width: 13px;
  height: 13px;
  background-color: red;
  border: 0.1px solid black;
  border-radius: 3px;
  display: flex;
  justify-content: center;
  align-items: center;
}

.image-checkbox:checked::after {
  content: "✓"; /* Add a white checkmark */
  color: white;
  font-size: 12px; /* Adjust size as needed */
  font-weight: bold;
}

  .image-link-button {
  position: absolute;
  bottom: 10px;
  left: 10px;
  padding: 6px 10px;
  background-color: blue;
  color: white;
  border: none;
  border-radius: 4px;
  cursor: pointer;
}

  .review-box {
  position: absolute;
  top: 10px;
  right: 120px;
  padding: 6px 10px;
  background-color: orange;
  color: white;
  border: none;
  border-radius: 4px;
}

  .ingestion-box {
  position: absolute;
  top: 10px;
  right: 70px;
  padding: 0px 10px;
  background-color: orange;
  color: white;
  border: none;
  border-radius: 4px;
  opacity: 80%;
}

  .blocked-box {
  position: absolute;
  top: 10px;
  right: 70px;
  padding: 6px 10px;
  background-color: orange;
  color: white;
  border: none;
  border-radius: 4px;
}

  .bounty-box {
  position: absolute;
  left: 50px;
