  padding: 6px 10px;
  background-color: orange;
  color: white;
  border: none;
  border-radius: 4px;
}
  .profile-box {
  position: absolute;
  left: 50px;
  top: 50px;
  padding: 6px 10px;
  background-color: orange;
  color: white;
  border: none;
  border-radius: 4px;
}

  .load-button {
